impl StfRoll {
    pub fn gens(&self) -> &'static [ParticleGeneratorParam] {
        self.gens
    }
    pub fn gens_va(&self) -> u32 {
        self.gens_va
    }
    pub fn ffs(&self) -> &'static [ParticleForceFieldParam] {
        self.ffs
    }
    pub fn ffs_va(&self) -> u32 {
        self.ffs_va
    }
    pub fn rand_x(&self) -> &'static [f32] {
        self.rand_x
    }
    pub fn rand_y(&self) -> &'static [f32] {
        self.rand_y
    }
    pub fn rand_y2(&self) -> &'static [f32] {
        self.rand_y2
    }
    pub fn lines(&self) -> &'static [StfRollLine] {
        self.lines
    }
    pub fn end_lines(&self) -> &'static [StfRollLine] {
        self.end_lines
    }
}

/// The volume's StfRoll.
pub fn of(v: Volume) -> &'static StfRoll {
    match v {
        Volume::Inf | Volume::Mut | Volume::Out => &INF_MUT_OUT,
        Volume::Qua => &QUA,
    }
}
